// Exact pinned Picture.cpp Bitmap(filename,FALSE) consumer; four captured wires only.
#include <windows.h>
#include <gdiplus.h>
#include <fstream>
#include <string>
#include <filesystem>
using namespace Gdiplus;
static std::wstring wide(const std::string&s){return std::wstring(s.begin(),s.end());}
int main(int argc,char**argv){if(argc!=3)return 2;ULONG_PTR token;GdiplusStartupInput in;if(GdiplusStartup(&token,&in,NULL)!=Ok)return 3;std::filesystem::create_directories(argv[2]);std::ofstream out(std::string(argv[2])+"/picture-bitmap.json");out<<"{\"consumer\":\"Pinned Picture.cpp Bitmap(filename,FALSE), direct natural GetPixel; no DrawImage\",\"cases\":[";const char*names[]={"path-gradient-square.emf","path-gradient-triangle-multicolor.emf","path-gradient-native-linear-alpha-off.emf","path-gradient-native-linear-alpha-on.emf"};bool first=true;for(auto name:names){if(!first)out<<",";first=false;std::string path=std::string(argv[1])+"/"+name;Bitmap b(wide(path).c_str(),FALSE);Status loaded=b.GetLastStatus();out<<"{\"file\":\""<<name<<"\",\"loadStatus\":"<<(int)loaded;if(loaded==Ok){UINT w=b.GetWidth(),h=b.GetHeight();RectF bounds;Unit unit;Status bs=b.GetBounds(&bounds,&unit);out<<",\"width\":"<<w<<",\"height\":"<<h<<",\"boundsStatus\":"<<(int)bs<<",\"bounds\":["<<bounds.X<<","<<bounds.Y<<","<<bounds.Width<<","<<bounds.Height<<"],\"boundsUnit\":"<<(int)unit<<",\"dpi\":["<<b.GetHorizontalResolution()<<","<<b.GetVerticalResolution()<<"]";std::ofstream raw(std::string(argv[2])+"/"+name+".rgba",std::ios::binary);Status ps=Ok;for(UINT y=0;y<h && ps==Ok;y++)for(UINT x=0;x<w;x++){Color c;ps=b.GetPixel(x,y,&c);if(ps!=Ok)break;unsigned char v[]={c.GetR(),c.GetG(),c.GetB(),c.GetA()};raw.write((char*)v,4);}out<<",\"directGetPixelStatus\":"<<(int)ps<<",\"rawBytes\":"<<(long long)raw.tellp();UINT size=0,count=0;GetImageEncodersSize(&count,&size);auto info=(ImageCodecInfo*)malloc(size);if(info&&GetImageEncoders(count,size,info)==Ok)for(UINT i=0;i<count;i++)if(wcscmp(info[i].MimeType,L"image/png")==0){Status save=b.Save(wide(std::string(argv[2])+"/"+name+".png").c_str(),&info[i].Clsid,NULL);out<<",\"directSavePNGStatus\":"<<(int)save;break;}free(info);}out<<"}";}out<<"]}";out.close();GdiplusShutdown(token);return 0;}
